def gen(rng):
    KEY = {}
    for d, ls in zip('23456789', ['abc', 'def', 'ghi', 'jkl', 'mno', 'pqrs', 'tuv', 'wxyz']):
        for c in ls:
            KEY[c] = d
    ALPHA = 'abcdefghijklmnopqrstuvwxyz'

    def enc(w):
        return ''.join(KEY[c] for c in w)

    def fmt(words, qs):
        return str(len(words)) + '\n' + '\n'.join(words) + '\n' + str(len(qs)) + '\n' + '\n'.join(qs)

    def rword(alpha, lo, hi):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(lo, hi)))

    def uniq(n, alpha, lo, hi):
        seen, out = set(), []
        tries = 0
        while len(out) < n and tries < n * 50:
            tries += 1
            w = rword(alpha, lo, hi)
            if w not in seen:
                seen.add(w)
                out.append(w)
        return out

    def queries(words, q, alpha_digits, lo, hi, p_hit=0.6):
        res = []
        for _ in range(q):
            r = rng.random()
            if words and r < p_hit:
                res.append(enc(rng.choice(words)))
            elif words and r < p_hit + 0.2:
                res.append(enc(rword(ALPHA, lo, hi)))
            else:
                res.append(''.join(rng.choice(alpha_digits) for _ in range(rng.randint(lo, hi))))
        return res

    tests = []
    tests.append(fmt(['careers', 'linkedin', 'hiring', 'interview', 'linkedgo'], ['2273377', '54653346']))
    tests.append(fmt(['a'], ['2']))
    tests.append(fmt(['a'], ['1']))
    tests.append(fmt(['a', 'b', 'c', 'd'], ['2', '3', '9']))
    tests.append(fmt(['zz', 'yy', 'xw'], ['99', '9', '999']))
    tests.append(fmt(['abc', 'bca', 'cab', 'acb'], ['222', '221', '22']))
    tests.append(fmt(['pqrs'], ['7777', '7777']))
    for _ in range(14):
        n = rng.randint(1, 8)
        alpha = rng.choice(['abc', 'abcdef', ALPHA, 'pqrsw'])
        words = uniq(n, alpha, 1, 5)
        tests.append(fmt(words, queries(words, rng.randint(1, 8), '123456789', 1, 5)))
    # max sized
    ws = uniq(10000, ALPHA, 20, 20)
    tests.append(fmt(ws, queries(ws, 10000, '23456789', 20, 20)))
    ws = uniq(10000, ALPHA, 1, 4)
    tests.append(fmt(ws, queries(ws, 10000, '23456789', 1, 4, 0.5)))
    ws = uniq(10000, 'abcdefghi', 10, 20)
    tests.append(fmt(ws, queries(ws, 10000, '234', 10, 20, 0.9)))
    ws = uniq(2000, 'abc', 7, 7)
    tests.append(fmt(ws, ['2222222'] * 20 + ['2222221', '222222']))
    return tests

